const MemoryRecordSchema = @import("memory_record_schema.zig").MemoryRecordSchema;

/// Configurations for overriding the reflection step of the episodic memory
/// strategy.
pub const EpisodicOverrideReflectionConfigurationInput = struct {
    /// The text to append to the prompt for reflection step of the episodic memory
    /// strategy.
    append_to_prompt: []const u8,

    /// Schema for metadata fields on records generated by this reflection override.
    memory_record_schema: ?MemoryRecordSchema = null,

    /// The model ID to use for the reflection step of the episodic memory strategy.
    model_id: []const u8,

    /// The namespaces to use for episodic reflection. Can be less nested than the
    /// episodic namespaces.
    namespaces: ?[]const []const u8 = null,

    /// The namespaceTemplates to use for episodic reflection. Can be less nested
    /// than the episodic namespaces.
    namespace_templates: ?[]const []const u8 = null,

    pub const json_field_names = .{
        .append_to_prompt = "appendToPrompt",
        .memory_record_schema = "memoryRecordSchema",
        .model_id = "modelId",
        .namespaces = "namespaces",
        .namespace_templates = "namespaceTemplates",
    };
};
